    "Classificatori variazionali, kernel quantistici, QCNN e barren plateau, più modelli generativi quantistici (qGAN, QCBM, Boltzmann machine, QuDDPM) ricalcati dai paper.": "Classificadores variacionais, kernels quânticos, QCNN, barren plateaus e modelos generativos quânticos de artigos: qGAN, QCBM, máquinas de Boltzmann e QuDDPM.",
    "DNA, sequenze, NGS, single-cell, GWAS, CRISPR e strutture proteiche, con gli schemi di AlphaFold2, ESM, Enformer, DNABERT e scGPT.": "ADN, sequências, NGS, single-cell, GWAS, CRISPR e estruturas proteicas, com diagramas de AlphaFold2, ESM, Enformer, DNABERT e scGPT.",
    "Componenti ottici in vista laterale, fasci laser, campo vicino e lontano, microscopia, fotonica integrata e figure di imaging computazionale e calcolo ottico (D2NN, reti di MZI, ptychography).": "Componentes óticos de perfil, lasers, campos próximo e distante, microscopia, fotónica integrada, imagem computacional e cálculo ótico: D2NN, redes MZI, pticografia.",
    "Molecole, cristalli, reazioni, docking e i modelli ML per chimica e materiali: MPNN, SchNet, EGNN, NequIP, JT-VAE, EDM, DiffDock, CDVAE e altri.": "Moléculas, cristais, reações, docking e ML para química e materiais: MPNN, SchNet, EGNN, NequIP, JT-VAE, EDM, DiffDock, CDVAE e mais.",
