    "Progetto tolto dall’elenco: la cartella e le figure restano sul disco": "プロジェクトをリストから削除しました。フォルダーと図はディスクに残ります",
    "Istologia, radiologia, oftalmologia, icone biomediche e schemi di colorazione virtuale, segmentazione e MIL.": "組織学、放射線学、眼科、生物医学アイコン、仮想染色、セグメンテーション、MIL の図。",
    "Segnali nel tempo e in frequenza, spettrogrammi, filtri, biosegnali e simboli dei diagrammi a blocchi.": "時間・周波数領域の信号、スペクトログラム、フィルター、生体信号、ブロック線図の記号。",
    "Riconoscimento di forme, rilevamento, segmentazione e gli schemi classici di computer vision.": "パターン認識、検出、セグメンテーション、従来のコンピュータービジョンの図。",
    "Agenti, ambienti e politiche; token, attenzione e gli schemi dei modelli linguistici.": "エージェント、環境、方策、トークン、注意機構、言語モデルの図。",
    "Alberi, SVM, clustering, validazione incrociata e i grafici tipici del machine learning.": "木、SVM、クラスタリング、交差検証、機械学習でよく使うグラフ。",
    "Manipolatori, robot mobili e con gambe, droni, sensori e mappe, schemi di controllo (PID, spazio di stato, MPC) e figure di robot learning tratte dai paper.": "マニピュレーター、移動・脚式ロボット、ドローン、センサー、地図、PID・状態空間・MPC 制御、論文に基づくロボット学習の図。",
    "Circuiti quantistici in stile libro di testo, sfera di Bloch, hardware e algoritmi: da Bell e teletrasporto a Grover, Shor, VQE e codici di correzione.": "教科書形式の量子回路、ブロッホ球、ハードウェア、Bell、テレポーテーション、Grover、Shor、VQE、誤り訂正符号。",
    "Classificatori variazionali, kernel quantistici, QCNN e barren plateau, più modelli generativi quantistici (qGAN, QCBM, Boltzmann machine, QuDDPM) ricalcati dai paper.": "変分分類器、量子カーネル、QCNN、勾配消失、論文に基づく量子生成モデル：qGAN、QCBM、ボルツマンマシン、QuDDPM。",
    "DNA, sequenze, NGS, single-cell, GWAS, CRISPR e strutture proteiche, con gli schemi di AlphaFold2, ESM, Enformer, DNABERT e scGPT.": "DNA、配列、NGS、単一細胞、GWAS、CRISPR、タンパク質構造と AlphaFold2、ESM、Enformer、DNABERT、scGPT の図。",
    "Componenti ottici in vista laterale, fasci laser, campo vicino e lontano, microscopia, fotonica integrata e figure di imaging computazionale e calcolo ottico (D2NN, reti di MZI, ptychography).": "側面図の光学部品、レーザー、近接場・遠方場、顕微鏡、集積フォトニクス、計算イメージング・光計算：D2NN、MZI 網、タイコグラフィー。",
    "Molecole, cristalli, reazioni, docking e i modelli ML per chimica e materiali: MPNN, SchNet, EGNN, NequIP, JT-VAE, EDM, DiffDock, CDVAE e altri.": "分子、結晶、反応、ドッキング、化学・材料向け機械学習：MPNN、SchNet、EGNN、NequIP、JT-VAE、EDM、DiffDock、CDVAE など。",
