    "Il server del gruppo non risponde. Controlla che il computer che lo ospita sia acceso e sulla stessa rete. Riprovo da solo.": "グループのサーバーが応答しません。サーバーを動かしているコンピューターの電源が入っていて、同じネットワークにあるか確認してください。自動的に再試行します。",
