    "Una stanza è una figura su cui lavorare insieme dal vivo, con i commenti. Resta aperta finché chi l’ha creata non la chiude.": "방은 댓글을 달며 함께 실시간으로 작업하는 도식입니다. 만든 사람이 닫을 때까지 열려 있습니다.",
    "Spegnere il server? I colleghi verranno scollegati, l’invito non varrà più e tutte le stanze verranno chiuse.": "서버를 끌까요? 동료들의 연결이 끊기고, 초대 코드는 더 이상 쓸 수 없으며, 모든 방이 닫힙니다.",
