    "Generative AI": "जनरेटिव AI",
    "Commento aggiunto: salva la figura per condividerlo": "टिप्पणी जुड़ी: साझा करने के लिए चित्र सहेजें",
    "Immagine inserita: è marcata come generata con l’IA": "छवि जुड़ी और AI से बनी के रूप में चिह्नित की गई",
    "Progetto tolto dall’elenco: la cartella e le figure restano sul disco": "परियोजना सूची से हटी; फ़ोल्डर और चित्र डिस्क पर हैं",
    "Istologia, radiologia, oftalmologia, icone biomediche e schemi di colorazione virtuale, segmentazione e MIL.": "ऊतक विज्ञान, रेडियोलॉजी, नेत्र विज्ञान, जैवचिकित्सा आइकन, वर्चुअल स्टेनिंग, विभाजन और MIL आरेख।",
    "Segnali nel tempo e in frequenza, spettrogrammi, filtri, biosegnali e simboli dei diagrammi a blocchi.": "समय और आवृत्ति सिग्नल, स्पेक्ट्रोग्राम, फ़िल्टर, जैवसिग्नल और ब्लॉक आरेख चिह्न।",
    "Riconoscimento di forme, rilevamento, segmentazione e gli schemi classici di computer vision.": "पैटर्न पहचान, पहचान, विभाजन और पारंपरिक कंप्यूटर विज़न आरेख।",
    "Agenti, ambienti e politiche; token, attenzione e gli schemi dei modelli linguistici.": "एजेंट, वातावरण और नीतियाँ; टोकन, अटेंशन और भाषा मॉडल आरेख।",
    "Alberi, SVM, clustering, validazione incrociata e i grafici tipici del machine learning.": "ट्री, SVM, क्लस्टरिंग, क्रॉस-वैलिडेशन और सामान्य मशीन लर्निंग चार्ट।",
    "Manipolatori, robot mobili e con gambe, droni, sensori e mappe, schemi di controllo (PID, spazio di stato, MPC) e figure di robot learning tratte dai paper.": "मैनिपुलेटर, मोबाइल और पैरों वाले रोबोट, ड्रोन, सेंसर, मानचित्र, PID/स्टेट-स्पेस/MPC नियंत्रण और शोधपत्रों के रोबोट लर्निंग आरेख।",
    "Circuiti quantistici in stile libro di testo, sfera di Bloch, hardware e algoritmi: da Bell e teletrasporto a Grover, Shor, VQE e codici di correzione.": "पाठ्यपुस्तक जैसे क्वांटम सर्किट, Bloch स्फीयर, हार्डवेयर और एल्गोरिदम: Bell, टेलीपोर्टेशन, Grover, Shor, VQE और त्रुटि-सुधार कोड।",
    "Classificatori variazionali, kernel quantistici, QCNN e barren plateau, più modelli generativi quantistici (qGAN, QCBM, Boltzmann machine, QuDDPM) ricalcati dai paper.": "वैरिएशनल क्लासिफ़ायर, क्वांटम कर्नेल, QCNN, बैरन प्लेटो और शोधपत्रों के क्वांटम जनरेटिव मॉडल: qGAN, QCBM, Boltzmann मशीन और QuDDPM।",
    "DNA, sequenze, NGS, single-cell, GWAS, CRISPR e strutture proteiche, con gli schemi di AlphaFold2, ESM, Enformer, DNABERT e scGPT.": "DNA, अनुक्रम, NGS, सिंगल-सेल, GWAS, CRISPR और प्रोटीन संरचनाएँ, साथ में AlphaFold2, ESM, Enformer, DNABERT और scGPT आरेख।",
    "Componenti ottici in vista laterale, fasci laser, campo vicino e lontano, microscopia, fotonica integrata e figure di imaging computazionale e calcolo ottico (D2NN, reti di MZI, ptychography).": "बगल से दिखते ऑप्टिकल भाग, लेज़र, निकट/दूर क्षेत्र, माइक्रोस्कोपी, एकीकृत फोटोनिक्स, कम्प्यूटेशनल इमेजिंग और ऑप्टिकल कंप्यूटिंग: D2NN, MZI नेटवर्क, ptychography।",
    "Molecole, cristalli, reazioni, docking e i modelli ML per chimica e materiali: MPNN, SchNet, EGNN, NequIP, JT-VAE, EDM, DiffDock, CDVAE e altri.": "अणु, क्रिस्टल, प्रतिक्रियाएँ, डॉकिंग और रसायन व पदार्थों के ML मॉडल: MPNN, SchNet, EGNN, NequIP, JT-VAE, EDM, DiffDock, CDVAE आदि।",
