    "Dentro ci sono tutte le sue figure, con lo stato di ognuna e la scadenza. Se la metti in una cartella condivisa, la vedono anche relatore e coautori.": "चित्र, उनकी स्थिति और अंतिम तिथि साथ रखें। साझा फ़ोल्डर से पर्यवेक्षक और सहलेखक भी देख सकते हैं।",
